#!/usr/bin/env bash
#SBATCH --partition=rtx5060ti16g
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=16
#SBATCH --job-name=w4a16-e016-release
#SBATCH --time=00:25:00
set -euo pipefail
: "${PROJECT_ROOT:?Absolute root}"
cd "$PROJECT_ROOT"
r=results/e016_20261109
tar --exclude='__pycache__' -czf "$r/c58-initial-prerequisite-source.tar.gz" scripts/e016
base64 -d <<'E016_PAYLOAD' | tar -xzf -

E016_PAYLOAD
source scripts/e016/env_arc.sh
trap 'rc=$?; echo "$rc" > "$R/updated-prerequisite.exit"; touch "$R/UPDATED_PREREQUISITE_FINISHED"; for ((i=0;i<300;i++)); do [[ -e "$R/UPDATED_PREREQUISITE_RETRIEVED" ]] && break; sleep 2; done; exit "$rc"' EXIT
allocation updated-prerequisite
prun /bin/hostname > "$R/updated-launcher.log" 2>&1
[[ $(grep -c "^$SLURM_JOB_NODELIST$" "$R/updated-launcher.log") == 1 ]]
{
 date --iso-8601=seconds
 lscpu; lscpu -e; cat /proc/cpuinfo; numactl --hardware; cat /proc/self/status
 gcc --version; mpirun --version; nvcc --version; compute-sanitizer --version
 nvidia-smi -q; nvidia-smi topo -m
 env | grep -E '^(SLURM_|OMP_|OMPI_|PATH=|PROJECT_ROOT=)' | sort
 findmnt -T "$PROJECT_ROOT"; df -h "$PROJECT_ROOT"
} > "$R/updated-metadata.txt" 2>&1
export PIP_CACHE_DIR="$PROJECT_ROOT/cache/pip"
if [[ ! -x "$E016_PYTHON" ]]; then
 run updated-venv python3.11 -m venv /tmp/e015-hpuvvad-20261109
 run updated-install "$E016_PYTHON" -m pip install -r scripts/e014/requirements.lock
fi
"$E016_PYTHON" -m pip freeze > "$R/updated-pip-freeze.txt"
diff -u scripts/e014/requirements.lock "$R/updated-pip-freeze.txt" > "$R/updated-dependency-diff.txt"
sha256sum scripts/e014/{model.py,fetch.py,prompts.json,validate.py,timeline.py} scripts/e015/{runner.py,run.py,checks.py} scripts/e016/*.* > "$R/updated-prerequisite-tooling.sha256"
small="$R/updated-checker-smoke"
mkdir "$small"
cp "$R/model.json" "$small/model.json"
for variant in G H; do
 run "updated-smoke_${variant}" "$E016_PYTHON" scripts/e016/run.py "$small" --stage smoke --variant "$variant" --context 128
done
touch "$R/UPDATED_SMOKE_CAPTURED"
